// Read a sheet.
LocalizationTable table = LocalizationCsv.Parse(File.ReadAllText(path));

foreach (string code in table.LocaleCodes)
    Debug.Log(code + ": " + table.TranslatedCount(code) + "/" + table.Keys.Count);

// Write one back out. alignColumns pads the columns into a readable table;
// leave it off for a file going straight into Excel.
string readable = LocalizationCsv.ToCsv(table, "key", true);
